using System.Text;

namespace InterfaceGenerator;

/// <summary>
/// Everything needed to write the generated file, as plain values.
/// </summary>
/// <remarks>
/// No Roslyn type appears here on purpose: this value is what the incremental pipeline compares
/// between runs, and a symbol or a syntax node would make it compare unequal on every keystroke
/// while pinning the compilation in memory.
/// </remarks>
internal readonly record struct InterfaceSpec(
    string HintName,
    string TypeNamespace,
    string TypeKeyword,
    string TypeName,
    string InterfaceNamespace,
    string InterfaceName,
    string Accessibility,
    string TypeParameters,
    EquatableArray<string> Constraints,
    EquatableArray<string> Members)
{
    private string QualifiedInterface =>
        InterfaceNamespace.Length == 0
            ? $"global::{InterfaceName}{TypeParameters}"
            : $"global::{InterfaceNamespace}.{InterfaceName}{TypeParameters}";

    public string Render()
    {
        StringBuilder builder = new StringBuilder()
            .AppendLine("// <auto-generated/>")
            .AppendLine("#nullable enable")
            .AppendLine();

        // The partial declaration that adds the interface to the base list. Constraints are
        // deliberately omitted: a partial declaration may repeat them or leave them out, and
        // repeating them means keeping two renderings of the same constraints in sync.
        string indent = Open(builder, TypeNamespace);
        builder
            .Append(indent).Append(Accessibility).Append(" partial ").Append(TypeKeyword).Append(' ')
            .Append(TypeName).Append(TypeParameters).Append(" : ").AppendLine(QualifiedInterface)
            // A brace body rather than `: IFoo;`: a semicolon-bodied type declaration needs
            // C# 12, and the generated file is compiled with the consumer's LangVersion.
            .Append(indent).AppendLine("{")
            .Append(indent).AppendLine("}");
        Close(builder, TypeNamespace);

        builder.AppendLine();

        // A second block rather than a shared one, even when the namespaces match: one code path
        // covers both, and the compiler is indifferent to the repetition.
        indent = Open(builder, InterfaceNamespace);
        builder
            .Append(indent).Append(Accessibility).Append(" interface ")
            .Append(InterfaceName).AppendLine(TypeParameters);

        foreach (string constraint in Constraints)
        {
            builder.Append(indent).Append("    ").AppendLine(constraint);
        }

        builder.Append(indent).AppendLine("{");

        foreach (string member in Members)
        {
            builder.Append(indent).Append("    ").AppendLine(member);
        }

        builder.Append(indent).AppendLine("}");
        Close(builder, InterfaceNamespace);

        return builder.ToString();
    }

    /// <summary>
    /// Opens a namespace block when there is one, and returns the indent its contents take.
    /// </summary>
    private static string Open(StringBuilder builder, string @namespace)
    {
        if (@namespace.Length == 0)
        {
            return string.Empty;
        }

        builder.Append("namespace ").AppendLine(@namespace).AppendLine("{");
        return "    ";
    }

    private static void Close(StringBuilder builder, string @namespace)
    {
        if (@namespace.Length != 0)
        {
            builder.AppendLine("}");
        }
    }
}
